ROHDATEN = """art,laenge
setosa,5.1
versicolor,7.0
setosa,4.9
virginica,6.3
versicolor,6.4
"""

def parse_zeilen(text):
    paare = []
    for zeile in text.strip().splitlines()[1:]:
        art, laenge = zeile.split(",")
        paare.append((art, float(laenge)))
    return paare

def mittel_pro_gruppe(paare):
    gruppen = {}
    for art, laenge in paare:
        gruppen.setdefault(art, []).append(laenge)
    ergebnis = {}
    for art, werte in gruppen.items():
        ergebnis[art] = sum(werte) / len(werte)
    return ergebnis

def main():
    paare = parse_zeilen(ROHDATEN)
    for art, mittel in mittel_pro_gruppe(paare).items():
        print(f"{art}: {mittel:.2f}")

if __name__ == "__main__":
    main()

